import React, { useEffect, useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import {
  buildTeenOnboardPayload,
  loadJson,
  saveJson,
  TEEN_STORAGE_KEYS,
} from '../../utils/teenTherapyStorage';
import TeenIntakeLayout from './TeenIntakeLayout';
import './TeenTherapyIntake.css';

const CONSENT_ITEMS = [
  {
    key: 'treatmentConsent',
    title: 'Consent for Treatment',
    description:
      'I consent to my child receiving therapy services from licensed mental health professionals through this platform. I understand that therapy sessions will be conducted online and that I may be involved in the treatment process as appropriate.',
  },
  {
    key: 'privacyConsent',
    title: 'Privacy and Confidentiality',
    description:
      "I understand that my child's therapy sessions are confidential, except as required by law (e.g., child abuse, harm to self or others). I consent to the collection and use of my child's health information as described in the Privacy Policy.",
  },
  {
    key: 'emergencyConsent',
    title: 'Emergency Contact Authorization',
    description:
      "I authorize the therapy platform to contact emergency services or the emergency contact I provided if there is a concern about my child's safety or well-being.",
  },
  {
    key: 'communicationConsent',
    title: 'Communication Consent',
    description:
      "I consent to receiving communications via email, phone, or text message regarding my child's therapy appointments, treatment updates, and important information. I understand I can opt out of non-essential communications at any time.",
  },
  {
    key: 'billingConsent',
    title: 'Billing and Payment Authorization',
    description:
      'I understand that I am responsible for payment of therapy services. I authorize charges to my payment method on file and agree to the billing terms and conditions.',
  },
];

export default function ParentConsent() {
  const navigate = useNavigate();
  const [consents, setConsents] = useState({
    treatmentConsent: false,
    privacyConsent: false,
    emergencyConsent: false,
    communicationConsent: false,
    billingConsent: false,
  });
  const [signature, setSignature] = useState('');
  const [error, setError] = useState('');
  const date = new Date().toISOString().split('T')[0];

  useEffect(() => {
    const parent = loadJson(TEEN_STORAGE_KEYS.parent);
    const child = loadJson(TEEN_STORAGE_KEYS.child);
    if (!parent.firstName) navigate('/teen/parent-guardian', { replace: true });
    else if (!child.firstName) navigate('/teen/child', { replace: true });
  }, [navigate]);

  const allAccepted = Object.values(consents).every(Boolean);

  const toggle = (key) => setConsents((c) => ({ ...c, [key]: !c[key] }));

  const onSubmit = (ev) => {
    ev.preventDefault();
    setError('');
    if (!allAccepted) {
      setError('Please accept all consents to proceed.');
      return;
    }
    if (!signature.trim()) {
      setError('Please provide your electronic signature (full name).');
      return;
    }

    const consentData = {
      ...consents,
      signature: signature.trim(),
      date,
      signedAt: new Date().toISOString(),
    };

    saveJson(TEEN_STORAGE_KEYS.consent, consentData);
    saveJson(TEEN_STORAGE_KEYS.onboard, buildTeenOnboardPayload(consentData));
    navigate('/questionnaire');
  };

  return (
    <TeenIntakeLayout
      step={3}
      title="Parent/Guardian Consent"
      subtitle="Please review and accept the following consents to register your child for therapy services."
    >
      <form onSubmit={onSubmit}>
        {CONSENT_ITEMS.map((item) => (
          <label key={item.key} className="teen-consent-item">
            <input
              type="checkbox"
              checked={consents[item.key]}
              onChange={() => toggle(item.key)}
            />
            <span>
              <strong>{item.title}</strong>
              {item.description}
            </span>
          </label>
        ))}

        <section className="teen-intake-card">
          <h2>Electronic Signature</h2>
          <p className="section-hint">
            By typing your full name below, you are providing your electronic signature, which has the
            same legal effect as a handwritten signature.
          </p>
          <div className="teen-field">
            <label>
              Full Name (Parent/Guardian) <span className="req">*</span>
            </label>
            <input
              value={signature}
              onChange={(e) => setSignature(e.target.value)}
              placeholder="Type your full name as your electronic signature"
            />
          </div>
          <p className="teen-field-hint">Date: {date}</p>
        </section>

        <div className="teen-note">
          <strong>Important Note</strong>
          <p>
            By proceeding, you acknowledge that you are the legal parent or guardian of the child being
            registered, and you have the authority to consent to treatment on their behalf. You also agree
            to our <Link to="/terms">Terms of Service</Link> and <Link to="/privacy">Privacy Policy</Link>.
          </p>
        </div>

        {error ? <p className="teen-field-error">{error}</p> : null}

        <div className="teen-actions">
          <button type="button" className="btn" onClick={() => navigate('/teen/child')}>
            Back
          </button>
          <button
            type="submit"
            className="btn primary"
            disabled={!allAccepted || !signature.trim()}
          >
            I Agree and Continue to Questionnaire
          </button>
        </div>
      </form>
    </TeenIntakeLayout>
  );
}
