import React from 'react';
import ChipSelect from './ChipSelect';
import { calculateAgeFromDob } from '../../services/coupleTherapyService';
import './CoupleTherapyIntake.css';

export default function CoupleSectionForm({ section, form, errors, onChange }) {
  const set = (name, val) => onChange({ ...form, [name]: val });

  const renderField = (field) => {
    const err = errors[field.name];

    if (field.type === 'consent_check') {
      return (
        <label key={field.name} className="teen-intake-consent-row">
          <input
            type="checkbox"
            checked={!!form[field.name]}
            onChange={(e) => set(field.name, e.target.checked)}
          />
          <span>
            <strong>{field.label}</strong>
            {field.description ? <small>{field.description}</small> : null}
          </span>
        </label>
      );
    }

    if (field.type === 'chips' || field.type === 'multiselect') {
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">
            {field.label}
            {field.required ? <span className="teen-intake-req"> *</span> : null}
          </label>
          <ChipSelect
            options={field.options}
            value={form[field.name]}
            onChange={(v) => set(field.name, v)}
            multi={field.type === 'multiselect'}
          />
          {err ? <p className="teen-field-error">{err}</p> : null}
        </div>
      );
    }

    if (field.type === 'yesno') {
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">{field.label}</label>
          <ChipSelect options={['Yes', 'No']} value={form[field.name]} onChange={(v) => set(field.name, v)} />
          {err ? <p className="teen-field-error">{err}</p> : null}
        </div>
      );
    }

    if (field.type === 'yesno_text') {
      const showText = form[field.name] === 'Yes';
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">{field.label}</label>
          <ChipSelect options={['Yes', 'No']} value={form[field.name]} onChange={(v) => set(field.name, v)} />
          {showText && field.textKey ? (
            <textarea
              className="teen-intake-input teen-intake-textarea"
              value={form[field.textKey] || ''}
              onChange={(e) => set(field.textKey, e.target.value)}
              placeholder={field.textPlaceholder || 'Please describe'}
              rows={4}
            />
          ) : null}
          {err ? <p className="teen-field-error">{err}</p> : null}
        </div>
      );
    }

    if (field.type === 'scale') {
      const min = field.min ?? 1;
      const max = field.max ?? 10;
      const nums = Array.from({ length: max - min + 1 }, (_, i) => String(i + min));
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">
            {field.label}
            {field.required ? <span className="teen-intake-req"> *</span> : null}
          </label>
          <ChipSelect
            options={nums}
            value={String(form[field.name] ?? '')}
            onChange={(v) => set(field.name, Number(v))}
          />
          {err ? <p className="teen-field-error">{err}</p> : null}
        </div>
      );
    }

    if (field.type === 'date') {
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">
            {field.label}
            {field.required ? <span className="teen-intake-req"> *</span> : null}
          </label>
          <input
            className={`teen-intake-input${err ? ' teen-intake-input-error' : ''}`}
            value={String(form[field.name] ?? '')}
            onChange={(e) => {
              const t = e.target.value;
              onChange({ ...form, [field.name]: t, age: calculateAgeFromDob(t) });
            }}
            placeholder="YYYY-MM-DD"
          />
          {form.age ? <p className="teen-intake-hint">Age: {form.age}</p> : null}
          {err ? <p className="teen-field-error">{err}</p> : null}
        </div>
      );
    }

    if (field.readOnly) {
      return (
        <div key={field.name} className="teen-intake-field">
          <label className="teen-intake-label">{field.label}</label>
          <p className="teen-intake-readonly">{form[field.name] || '—'}</p>
        </div>
      );
    }

    const isArea = field.type === 'textarea';
    const Input = isArea ? 'textarea' : 'input';
    return (
      <div key={field.name} className="teen-intake-field">
        <label className="teen-intake-label">
          {field.label}
          {field.required ? <span className="teen-intake-req"> *</span> : null}
        </label>
        <Input
          className={`teen-intake-input${isArea ? ' teen-intake-textarea' : ''}${err ? ' teen-intake-input-error' : ''}`}
          value={String(form[field.name] ?? '')}
          onChange={(e) =>
            set(field.name, field.type === 'number' ? e.target.value.replace(/\D/g, '') : e.target.value)
          }
          placeholder={field.placeholder}
          type={field.type === 'email' ? 'email' : field.type === 'phone' ? 'tel' : 'text'}
          rows={isArea ? 4 : undefined}
        />
        {err ? <p className="teen-field-error">{err}</p> : null}
      </div>
    );
  };

  return (
    <div className="couple-section-form">
      <h2 className="teen-intake-section-title">{section.title}</h2>
      {section.subtitle ? <p className="teen-intake-section-sub">{section.subtitle}</p> : null}
      {section.therapistOnly ? (
        <div className="couple-private-banner">Therapist-only — not shared with your partner</div>
      ) : null}
      {section.fields.map(renderField)}
    </div>
  );
}
