import React, { useCallback, useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { COUPLE_STATUSES } from '../../utils/coupleTherapyConfig';
import {
  loadCouple,
  sendPartnerBInvitation,
  navigateAfterCoupleIntake,
} from '../../services/coupleTherapyService';
import './CoupleTherapyIntake.css';

export default function CoupleWaitingPartner() {
  const navigate = useNavigate();
  const location = useLocation();
  const coupleId = location.state?.coupleId || localStorage.getItem('th.coupleId');
  const [couple, setCouple] = useState(null);
  const [inviteUrl, setInviteUrl] = useState(location.state?.inviteUrl || '');
  const [loading, setLoading] = useState(true);
  const [resending, setResending] = useState(false);
  const [message, setMessage] = useState('');

  const refresh = useCallback(async () => {
    if (!coupleId) return;
    setLoading(true);
    try {
      const data = await loadCouple(coupleId);
      setCouple(data);
      if (data?.partnerB?.inviteUrl) setInviteUrl(data.partnerB.inviteUrl);

      if (data?.partnerB?.intakeComplete && data?.partnerA?.intakeComplete) {
        await navigateAfterCoupleIntake(navigate, coupleId, 'partnerA');
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  }, [coupleId, navigate]);

  useEffect(() => {
    refresh();
    const interval = setInterval(refresh, 15000);
    return () => clearInterval(interval);
  }, [refresh]);

  const onResend = async () => {
    setResending(true);
    setMessage('');
    try {
      const res = await sendPartnerBInvitation(coupleId);
      if (res?.inviteUrl) setInviteUrl(res.inviteUrl);
      setMessage('Invitation sent again.');
    } catch (e) {
      setMessage('Could not send email — share the link below with your partner.');
    } finally {
      setResending(false);
    }
  };

  const onShare = async () => {
    if (!inviteUrl) return;
    if (navigator.share) {
      await navigator.share({ title: 'NessaHub couple therapy', text: `Join me for couple therapy: ${inviteUrl}` });
    } else {
      await navigator.clipboard.writeText(inviteUrl);
      setMessage('Link copied to clipboard.');
    }
  };

  if (loading && !couple) {
    return <div className="teen-intake-page couple-centered">Loading…</div>;
  }

  const bDone = couple?.partnerB?.intakeComplete;
  const partnerBName = couple?.partnerB?.name || 'Partner B';

  return (
    <div className="teen-intake-page">
      <div className="couple-banner-ok">
        <h2>Waiting for {partnerBName}</h2>
        <p>
          Your intake is complete.{' '}
          {bDone
            ? `${partnerBName} has finished too.`
            : `${partnerBName} still needs to create their account and complete their private intake.`}
        </p>
      </div>

      <div className="couple-card">
        <h3>Status</h3>
        <p>You: ✓ Intake complete</p>
        <p>
          {partnerBName}: {bDone ? '✓ Complete' : '⏳ Pending'}
        </p>
        <p className="couple-muted">Couple status: {couple?.status || COUPLE_STATUSES.AWAITING_PARTNER_B}</p>
      </div>

      {inviteUrl ? (
        <div className="couple-card">
          <h3>Partner invitation</h3>
          <p className="couple-invite-link">{inviteUrl}</p>
          <div className="couple-intake-footer">
            <button type="button" className="couple-btn-ghost" onClick={onShare}>
              Share link
            </button>
            <button type="button" className="couple-btn-ghost" onClick={onResend} disabled={resending}>
              {resending ? 'Sending…' : 'Resend email'}
            </button>
          </div>
        </div>
      ) : null}

      {message ? <p className="teen-intake-hint">{message}</p> : null}

      <button type="button" className="teen-intake-submit" onClick={() => navigate('/couple/dashboard', { state: { coupleId } })}>
        Open couple dashboard
      </button>
    </div>
  );
}
